/* EPR handoff preparation. No network request, acknowledgement or retention action. */
let pendingEprDraft=null,eprComposerPatient=null;
const eprDestinations={rio:'RiO',emis:'EMIS',other:'Other EPR'};
function eprDrafts(){if(!Array.isArray(state.eprHandoffDrafts))state.eprHandoffDrafts=[];return state.eprHandoffDrafts;}
function patientEprDrafts(){return eprDrafts().map((draft,index)=>({...draft,index})).filter(d=>d.patientId===state.selectedPatientId);}
function eprDraftSourceChanged(d){const r=state.patientRecords[d.patientId];return !r||!r.signed||r.note!==d.sourceText||r.version!==d.sourceVersion||r.revision!==d.sourceRevision||r.noteTemplate!==d.sourceTemplate;}
function eprSnapshotKey(d){return JSON.stringify([d.patientId,d.sourceText,d.sourceVersion,d.sourceRevision,d.sourceTemplate,d.destination,d.context]);}
function eprReadinessRows(){const r=state.patientRecords[currentPatient().id];return [{title:'Current document',detail:r.note.trim()?'Version '+r.version+' is available in this workspace.':'Prepare a document before creating a handoff draft.',status:r.note.trim()?'Available':'Needed',local:!!r.note.trim(),action:"nav('N')",label:'Open document'}, {title:'Document review',detail:r.signed?'Local review recorded for the current version. This is not a clinical signature.':'Review the exact document against its source.',status:r.signed?'Local review recorded':'Needed',local:r.signed,action:"openDocumentForReview(state.selectedPatientId)",label:r.signed?'View document':'Review document'}, {title:'Patient matching',detail:'Date of birth and NHS number are not supplied. External patient matching has not been performed.',status:'Not verified',local:false,action:"feature('NHS03')",label:'Matching requirements'}, {title:'Authorised EPR connection',detail:'No authorised destination, authenticated submission service or receiving-record mapping is connected.',status:'Not connected',local:false,action:"nav('connections')",label:'Connection details'}];}
function eprReadinessPanel(){return `<section class="panel epr-requirements"><div class="panel-head"><div><span class="eyebrow">REQUIREMENTS</span><h2>Before submission</h2></div><span class="pill amber">Blocked</span></div>${eprReadinessRows().map(r=>`<div class="epr-requirement"><div class="epr-requirement-heading"><h3>${esc(r.title)}</h3><span class="pill ${r.local?'green':'grey'}">${esc(r.status)}</span></div><p>${esc(r.detail)}</p><button class="text-btn" onclick="${r.action}">${esc(r.label)} ${icon('arrow')}</button></div>`).join('')}</section>`;}
function eprStageMarkup(){const drafts=patientEprDrafts(),current=drafts.some(d=>!eprDraftSourceChanged(d));return `<ol class="epr-stages" aria-label="EPR handoff stages"><li class="${state.signed?'epr-local-complete':''}"><span>1</span><div><strong>Review document</strong><small>${state.signed?'Recorded locally':'Review needed'}</small></div></li><li class="${current?'epr-local-complete':''}"><span>2</span><div><strong>Prepare draft</strong><small>${current?'Current source retained':'No current-source draft'}</small></div></li><li><span>3</span><div><strong>Send to EPR</strong><small>Not connected</small></div></li><li><span>4</span><div><strong>Confirm receipt</strong><small>No acknowledgement</small></div></li></ol>`;}
function eprDraftListMarkup(){const drafts=patientEprDrafts();return `<section class="panel epr-draft-list"><div class="panel-head"><div><h2>Prepared handoff drafts</h2><p>Exact document copies for ${esc(currentPatient().name)}.</p></div><span class="pill grey">${drafts.length}</span></div>${drafts.length?drafts.map(d=>`<article class="epr-draft-row"><span class="document-symbol">${icon('file')}</span><div><h3>${esc(eprDestinations[d.destination]||'Unspecified EPR')} · Note v${esc(d.sourceVersion)}</h3><p>${esc(patientActivityDate(d.createdAt))} · UK time</p><div class="epr-draft-tags"><span class="pill grey">Draft · Not sent</span><span class="pill ${eprDraftSourceChanged(d)?'amber':'green'}">${eprDraftSourceChanged(d)?'Source changed · Review needed':'Matches reviewed source'}</span></div></div><button onclick="inspectEprDraft(${d.index})">Inspect draft</button></article>`).join(''):`<div class="workspace-empty"><span class="empty-symbol">${icon('link')}</span><h3>No handoff drafts prepared</h3><p>Retain the exact reviewed document and intended destination before any future submission workflow.</p><button ${state.signed?'':'disabled'} onclick="openEprDraftComposer()">Prepare handoff draft</button>${!state.signed?'<p class="fine">Review the current document first.</p>':''}</div>`}<p class="fine">Prepared drafts stay in this development workspace. Selecting RiO or EMIS does not enable a connection or confirm a receiving patient record.</p></section>`;}
function eprSourcePanel(){return `<section class="panel epr-current-document"><div class="panel-head"><div><span class="eyebrow">CURRENT SOURCE</span><h2>${esc(documentTitle(state.noteTemplate))}</h2></div><span class="pill ${state.signed?'green':'grey'}">${state.signed?'Reviewed locally':state.note.trim()?'Unsigned draft':'Not started'}</span></div>${state.note.trim()?`<p class="epr-source-meta">${esc(currentPatient().name)} · ${esc(state.selectedPatientId)} · Version ${state.version}</p><pre class="review-copy">${esc(state.note)}</pre><div class="epr-source-actions"><button onclick="nav('N')">Open document</button><button onclick="openDocumentActivity(state.selectedPatientId)">Version history</button></div>`:'<p class="fine">No source document is available for this patient.</p><button onclick="nav(\'N\')">Start document</button>'}</section>`;}
uiWorkflowFunctions.I=function(){return `<div class="epr-connection-banner"><span class="epr-status-symbol">${icon('link')}</span><div><strong>EPR submission is not connected</strong><p>Prepare and inspect a local draft. No document has been sent to RiO, EMIS or another NHS system.</p></div><button onclick="nav('connections')">Connection status ${icon('arrow')}</button></div>${eprStageMarkup()}<div class="epr-workspace"><section><div class="epr-workspace-actions"><div><h2>Document handoff</h2><p>Keep the reviewed source and delivery state visible.</p></div><button class="primary" ${state.signed?'':'disabled'} onclick="openEprDraftComposer()">${icon('plus')} Prepare draft</button></div>${eprSourcePanel()}${eprDraftListMarkup()}</section><aside>${eprReadinessPanel()}<section class="panel epr-receipt-panel"><span class="eyebrow">RECEIPT & RETENTION</span><h2>No receipt recorded</h2><dl><dt>Submission reference</dt><dd>None — not sent</dd><dt>Receiving record</dt><dd>Not matched</dd><dt>Acknowledgement</dt><dd>None received</dd><dt>Retention action</dt><dd>None performed</dd></dl><p>No recording deletion is triggered by preparing, inspecting or exporting a draft.</p><button class="text-btn" onclick="feature('I04')">Retention dependency ${icon('arrow')}</button></section></aside></div>`;};
function openEprDraftComposer(values={}){pendingEprDraft=null;eprComposerPatient=null;if(!state.signed||!state.note.trim())return toast('Review the current document before preparing a handoff draft.');const p=currentPatient();eprComposerPatient=p.id;modal('Prepare EPR handoff draft',`<div class="handover-identity"><strong>${esc(p.name)}</strong><span>${esc(p.id)} · Reviewed document v${state.version}</span></div><form id="epr-draft-composer" onsubmit="event.preventDefault();reviewEprDraft(this)"><div class="form-group"><label for="epr-destination">Intended EPR</label><select class="field" id="epr-destination" name="destination">${taskOptions([['','Choose an intended system'],...Object.entries(eprDestinations)],values.destination||'')}</select><p class="fine">All destinations are unconnected. This records intent only.</p></div><div class="form-group"><label for="epr-context">Administrative handoff note (optional)</label><textarea class="field" id="epr-context" name="context" maxlength="1200" rows="3" placeholder="Use fictional information only">${esc(values.context||'')}</textarea></div><p id="epr-draft-error" class="task-error" role="alert"></p><p class="notice">The source remains exactly as reviewed. Patient matching and authorised submission are still required.</p></form>`,`<button onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="epr-draft-composer">Review handoff draft</button>`);document.getElementById('epr-destination')?.focus?.();}
function reviewEprDraft(form){const destination=form.destination.value,context=form.context.value.trim();if(eprComposerPatient!==state.selectedPatientId||!state.signed||!state.note.trim()||!Object.hasOwn(eprDestinations,destination)||context.length>1200){document.getElementById('epr-draft-error').textContent='Choose an intended EPR and use a reviewed document. Keep the handoff note within 1,200 characters.';return;}const p=currentPatient();pendingEprDraft={patientId:p.id,patientName:p.name,sourceText:state.note,sourceVersion:state.version,sourceRevision:state.revision,sourceTemplate:state.noteTemplate,destination,context};modal('Review EPR handoff draft',eprDraftDetailMarkup(pendingEprDraft)+`<label class="consent"><input type="checkbox" id="epr-draft-confirm"><span>I have checked the patient, intended system and exact document in this draft.</span></label><p id="epr-review-error" class="task-error" role="alert"></p>`,`<button onclick="pendingEprDraft=null;closeModal()">Cancel</button><button onclick="editPendingEprDraft()">Back to edit</button><button class="primary" onclick="confirmEprDraft()">Save local draft</button>`);}
function editPendingEprDraft(){const d=pendingEprDraft;if(!d)return;if(d.patientId!==state.selectedPatientId||!state.signed){document.getElementById('epr-review-error').textContent='The patient or document review changed. Your handoff note remains here; review the document before preparing a new draft.';return;}openEprDraftComposer({destination:d.destination,context:d.context});document.getElementById('epr-context')?.focus?.();}
function eprDraftDetailMarkup(d){return `<div class="handover-identity"><strong>${esc(d.patientName)}</strong><span>${esc(d.patientId)} · Document v${esc(d.sourceVersion)}</span></div><dl class="epr-draft-details"><dt>Intended system</dt><dd>${esc(eprDestinations[d.destination]||'Unspecified')} · Not connected</dd><dt>Patient match</dt><dd>Not verified · Synthetic record only</dd><dt>Delivery status</dt><dd>Not sent · No acknowledgement</dd></dl>${d.context?`<h3 class="epr-context-heading">Administrative handoff note</h3><p class="handover-message">${esc(d.context)}</p>`:''}<details class="task-source" open><summary>Exact reviewed document · Version ${esc(d.sourceVersion)}</summary><pre class="review-copy">${esc(d.sourceText)}</pre></details><p class="fine">This is an illustrative local draft, not a validated FHIR resource or accepted EPR submission.</p>`;}
function confirmEprDraft(){const d=pendingEprDraft;if(!d)return;if(d.patientId!==state.selectedPatientId||eprDraftSourceChanged(d)||state.noteTemplate!==d.sourceTemplate){document.getElementById('epr-review-error').textContent='The patient or source changed. Close this review and prepare a fresh draft.';return;}if(!document.getElementById('epr-draft-confirm')?.checked){document.getElementById('epr-review-error').textContent='Check the draft and confirm before saving.';return;}const existing=eprDrafts().find(x=>eprSnapshotKey(x)===eprSnapshotKey(d));let saved;if(existing){saved=save();}else{eprDrafts().unshift({...d,createdAt:new Date().toISOString(),submissionStatus:'NOT_SENT',acknowledgement:null,retentionAction:'NONE'});saved=audit(d.patientId+': EPR handoff draft prepared locally. No submission or retention action.');}pendingEprDraft=null;closeModal();render();toast(saved?(existing?'An identical handoff draft is already prepared. Not sent.':'Handoff draft saved locally. Not sent.'):'Handoff draft remains in this tab only. Saving failed. Not sent.');}
function inspectEprDraft(index){const d=eprDrafts()[index];if(!d||d.patientId!==state.selectedPatientId)return;modal('EPR handoff draft',`${eprDraftSourceChanged(d)?'<p class="notice amber">The current source has changed. This draft retains the earlier reviewed document. Prepare a new draft after reviewing the current version.</p>':''}${eprDraftDetailMarkup(d)}<div class="epr-send-block"><button disabled aria-describedby="epr-send-reason">Send to EPR</button><p id="epr-send-reason">Unavailable: authorised submission and patient matching are not connected.</p></div>`,`<button onclick="closeModal()">Close</button><button class="primary" onclick="exportEprDraft(${index})">Export draft copy</button>`);}
function exportEprDraft(index){const d=eprDrafts()[index];if(!d||d.patientId!==state.selectedPatientId)return;download(`${d.patientId}-epr-handoff-v${d.sourceVersion}-draft.txt`,`DEEPSYNAPS CLINICAL ADMIN\nILLUSTRATIVE HANDOFF DRAFT — NOT SENT\nSynthetic development workspace. Not a validated FHIR resource.\n\nPatient: ${d.patientName} (${d.patientId})\nIntended EPR: ${eprDestinations[d.destination]||'Unspecified'} — NOT CONNECTED\nSource version: ${d.sourceVersion}\nPrepared: ${d.createdAt}\nPatient matching: NOT VERIFIED\nSubmission reference: NONE\nAcknowledgement: NONE\nRetention action: NONE\n${eprDraftSourceChanged(d)?'SOURCE CHANGED — REVIEW CURRENT DOCUMENT BEFORE PREPARING A NEW DRAFT\n':''}\nADMINISTRATIVE HANDOFF NOTE\n${d.context||'Not supplied'}\n\nEXACT REVIEWED DOCUMENT\n${d.sourceText}\n\nExporting this copy does not submit it or trigger recording deletion.`, 'text/plain');}
const eprPriorPatientSelect=selectPatient;
selectPatient=function(id){if(!demoPatients.some(p=>p.id===id))return;pendingEprDraft=null;eprComposerPatient=null;return eprPriorPatientSelect(id);};
document.getElementById('dialog').addEventListener('close',()=>{pendingEprDraft=null;eprComposerPatient=null;});
document.getElementById('dialog').addEventListener('cancel',()=>{pendingEprDraft=null;eprComposerPatient=null;});
render();
